import java.nio.file.*;
import java.util.*;
import java.time.*;
import com.project.backend.data.DataManifest;
import com.project.backend.conversation.ProductCategory;
import com.project.backend.product.*;
import com.project.backend.warranty.*;
import com.project.backend.mcp.retrieval.KnowledgeRetriever;
import com.project.backend.mcp.tool.ToolDataCatalog;
import tools.jackson.databind.json.JsonMapper;

public class ManufacturerDataAudit {
    public static void main(String[] args) throws Exception {
        var catalog = new ToolDataCatalog(DataManifest.classpath());
        var retriever = KnowledgeRetriever.lexical(catalog);
        var cases = List.of(
            List.of("user-fridge-exact", "REFRIGERATOR", "S836MEE022", "냉장고가 시원하지 않아요."),
            List.of("fridge-cooling", "REFRIGERATOR", "S836MEE022", "냉장고가 시원하지 않고 냉장칸 음식이 미지근해요."),
            List.of("fridge-odor", "REFRIGERATOR", "S836MEE022", "냉장고 안에서 냄새가 나요."),
            List.of("washer-vibration", "WASHER", "FX24ENER", "탈수할 때 세탁기가 많이 흔들려요."),
            List.of("washer-softener", "WASHER", "F12WVAR", "섬유유연제가 나오지 않아요."),
            List.of("dryer-drain", "DRYER", "RD21ESE", "배수가 안 돼요."),
            List.of("dryer-door", "DRYER", "RD21ESE", "문이 안 닫혀요."),
            List.of("fridge-spec-volume", "REFRIGERATOR", "M876GBB231", "전체 용량은 몇 리터인가요?"),
            List.of("washer-add-laundry", "WASHER", "F12WVAR", "세탁 중 빨래 추가 방법이 궁금해요.")
        );
        var report = new LinkedHashMap<String,Object>();
        report.put("scope", "Actual KnowledgeRetriever.lexical; no Spring server, model API or user DB; diagnostic probes, not a quality score");
        report.put("data_version", catalog.version);
        var probes = new ArrayList<Map<String,Object>>();
        for (var c : cases) {
            var result = retriever.retrieve(c.get(3), c.get(1), c.get(2), "MANUAL", null, 3);
            var counts = new TreeMap<String,Integer>();
            for (String id : catalog.knowledgeById.keySet())
                if (retriever.eligible(id, c.get(1), c.get(2))) counts.merge(id.split("-")[0], 1, Integer::sum);
            var row = new LinkedHashMap<String,Object>();
            row.put("id", c.get(0)); row.put("category", c.get(1)); row.put("model", c.get(2)); row.put("query", c.get(3));
            row.put("eligible_by_origin_prefix_all_topics", counts);
            row.put("documents", result.documents()); row.put("safety", result.safety()); row.put("mode", result.mode());
            probes.add(row);
        }
        report.put("probes", probes);
        var registered = new UserProduct(null);
        var purchase = LocalDate.parse("2026-05-05");
        registered.update(new ProductRequest(ProductCategory.REFRIGERATOR, "냉장고", "S836MEE022", purchase.toString(), null, "제주특별자치도 제주시", null), purchase);
        var warranty = new WarrantyService(new WarrantyCatalog(), Clock.fixed(Instant.parse("2026-10-15T03:00:00Z"), ZoneId.of("Asia/Seoul")));
        var saved = registered.warranty();
        var registration = new LinkedHashMap<String,Object>();
        registration.put("scope", "Synthetic entity populated by the same registration update method; no live customer DB");
        registration.put("model", saved.modelName()); registration.put("purchase_date", saved.purchaseDate());
        registration.put("proof_available", saved.proofAvailable()); registration.put("domestic_new_household", saved.domesticNewHousehold());
        registration.put("delivery_sido", registered.getDeliverySido()); registration.put("delivery_sigungu", registered.getDeliverySigungu());
        registration.put("address_present", registered.response().address()!=null);
        registration.put("warranty_from_saved_input", warranty.check(saved));
        registration.put("warranty_with_explicit_conditions", warranty.check(new WarrantyModels.Request(ProductCategory.REFRIGERATOR, "S836MEE022", purchase, null, null, null, null, true, true)));
        report.put("registration_probe", registration);
        Files.writeString(Path.of(args[0]), JsonMapper.builder().build().writeValueAsString(report) + "\n");
        System.out.println("Wrote " + probes.size() + " offline retrieval probes; records=" + catalog.knowledge.size());
    }
}

